package java.util;
public abstract class AbstractCollection<E> implements Collection<E> { protected AbstractCollection(){} public abstract Iterator<E> iterator(); public abstract int size(); public boolean isEmpty(){return size()==0;} public boolean contains(Object o){for(E e:this)if(Objects.equals(o,e))return true;return false;} public Object[] toArray(){Object[] a=new Object[size()];int i=0;for(E e:this)a[i++]=e;return a;} public <T> T[] toArray(T[] a){int n=size();if(a.length<n)throw new UnsupportedOperationException("array allocation requires reflection");int i=0;for(E e:this)a[i++]=(T)e;if(a.length>n)a[n]=null;return a;} public boolean add(E e){throw new UnsupportedOperationException();} public boolean remove(Object o){Iterator<E> i=iterator();while(i.hasNext())if(Objects.equals(o,i.next())){i.remove();return true;}return false;} public boolean containsAll(Collection<?> c){for(Object e:c)if(!contains(e))return false;return true;} public boolean addAll(Collection<? extends E> c){boolean r=false;for(E e:c)r|=add(e);return r;} public boolean removeAll(Collection<?> c){boolean r=false;Iterator<E> i=iterator();while(i.hasNext())if(c.contains(i.next())){i.remove();r=true;}return r;} public boolean retainAll(Collection<?> c){boolean r=false;Iterator<E> i=iterator();while(i.hasNext())if(!c.contains(i.next())){i.remove();r=true;}return r;} public void clear(){Iterator<E> i=iterator();while(i.hasNext()){i.next();i.remove();}} public String toString(){StringBuilder b=new StringBuilder("[");Iterator<E> i=iterator();while(i.hasNext()){Object e=i.next();b.append(e==this?"(this Collection)":String.valueOf(e));if(i.hasNext())b.append(", ");}return b.append(']').toString();} }
